{ id:'B:kh02-09', skill:'measure', read:'7 phút', t:'Có nên bỏ bớt một tệp khách đang mang doanh thu?',
  situation:'Một hãng nước chấm đóng chai bán cho ba tệp: siêu thị ở thành phố, quán ăn, và đại lý ở các tỉnh xa. Tệp đại lý tỉnh mang 500 triệu doanh thu mỗi năm, lãi gộp 20%. Nhưng chi phí vận chuyển, chiết khấu thêm và nhân viên đi tuyến cho riêng tệp này tốn 130 triệu. Ai cũng ngại cắt vì “mất doanh thu”.',
  concept:{ name:'Lãi sau chi phí phục vụ của từng tệp',
    body:'Mỗi tệp không chỉ mang doanh thu mà còn kéo theo chi phí riêng để phục vụ: giao hàng, chiết khấu, nhân sự, hỗ trợ. Một tệp có doanh thu đẹp vẫn có thể lỗ khi trừ hết các chi phí này. Bỏ bớt tệp là quyết định khó vì doanh thu giảm thấy ngay, còn lợi ích — tiền và người được giải phóng — cần thời gian mới hiện ra. Trước khi bỏ, hãy thử sửa: đổi cách phục vụ, tăng đơn tối thiểu. Nếu vẫn lỗ, bỏ đi để dồn lực vào tệp đang thắng thường là quyết định đúng.' },
  example:'Tệp đại lý tỉnh: lãi gộp 500 × 20% = 100 triệu, trừ 130 triệu chi phí phục vụ → lỗ 30 triệu mỗi năm. Nhóm thử tăng đơn tối thiểu và gom tuyến giao hai tuần một lần; chi phí chỉ giảm còn 115 triệu, vẫn lỗ. Họ chuyển các đại lý sang một nhà phân phối vùng và rút nhân viên tuyến về chăm quán ăn — tệp đang tăng nhanh nhất.',
  takeaway:'Doanh thu không phải lãi: tệp nào lỗ sau chi phí phục vụ thì sửa, sửa không được thì bỏ.',
  apply:'Nghĩ về một nhóm khách của một doanh nghiệp bạn biết mà phục vụ rất tốn công. Liệt kê ba chi phí riêng của nhóm đó.',
  mistakes:['Giữ tệp vì doanh thu mà không tính chi phí phục vụ riêng.','Cắt tệp ngay mà chưa thử sửa cách phục vụ.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: tệp đại lý tỉnh có đáng giữ không?',
    options:[{k:'a',t:'Giữ vì 500 triệu doanh thu là quá lớn để bỏ đi mà không tiếc'},{k:'b',t:'Bỏ ngay vì tỉnh xa lúc nào cũng khó làm và ít có lợi nhuận'},
             {k:'c',t:'Giữ vì bỏ tệp sẽ làm hình ảnh thương hiệu bị thu hẹp lại'},{k:'d',t:'Phải so lãi gộp với chi phí phục vụ riêng rồi mới quyết định'}],
    answer:'d', why:{a:'Doanh thu che mất việc tệp có thể đang lỗ.',
      b:'Không phải lúc nào tỉnh xa cũng lỗ; cần tính.',
      c:'Hình ảnh không bù được khoản lỗ lặp lại hằng năm.',
      d:'Đúng. Chỉ phép tính mới cho biết tệp đang lãi hay lỗ.'} },
  { type:'mcq', stem:'Tính ra tệp đại lý tỉnh lỗ 30 triệu/năm. Bạn đề xuất gì trước?',
    options:[{k:'a',t:'Cắt ngay toàn bộ đại lý tỉnh từ tháng sau để chặn khoản lỗ'},{k:'b',t:'Giữ nguyên và tăng quảng cáo ở tỉnh để kéo doanh thu lên bù lỗ'},
             {k:'c',t:'Thử sửa cách phục vụ trước, như đơn tối thiểu và gom tuyến giao'},{k:'d',t:'Tăng giá cho đại lý tỉnh thêm 30% để đủ bù chi phí vận chuyển'}],
    answer:'c', why:{a:'Cắt ngay bỏ qua khả năng sửa được với chi phí thấp.',
      b:'Thêm doanh thu mà mỗi đồng vẫn kéo chi phí phục vụ cao thì lỗ khó giảm.',
      c:'Đúng. Sửa trước, bỏ sau: có bằng chứng rồi mới cắt.',
      d:'Tăng 30% dễ làm đại lý bỏ sang hàng khác; vẫn nên thử cách phục vụ trước.'} },
  { type:'calc', stem:'Tệp đại lý tỉnh: doanh thu 500 triệu/năm, lãi gộp 20%, chi phí phục vụ riêng 130 triệu. Lãi (hoặc lỗ) của tệp là bao nhiêu triệu đồng? (lỗ ghi số âm)',
    unit:'triệu đồng', ans:-30, tol:0.5, wrong:[[100,'QUEN_CHI_PHI_BIEN_DOI'],[370,'NHAM_GIA_VON']], errors:['QUEN_CHI_PHI_BIEN_DOI','NHAM_GIA_VON'],
    steps:['Lãi gộp = 500 × 20% = 100 triệu.','Trừ chi phí phục vụ: 100 − 130 = <b>−30 triệu</b> (lỗ).'] },
  { type:'mcq', stem:'Vì sao bỏ tệp thường bị trì hoãn dù đã thấy lỗ?',
    options:[{k:'a',t:'Doanh thu giảm thấy ngay, còn lợi ích cần thời gian mới hiện ra'},{k:'b',t:'Vì luật kinh doanh không cho phép ngừng bán cho đại lý đã ký hợp đồng'},
             {k:'c',t:'Vì kế toán không tách được chi phí phục vụ riêng cho từng tệp khách'},{k:'d',t:'Vì đối thủ sẽ lập tức chiếm tệp đó và dùng nó để tấn công ngược lại'}],
    answer:'a', why:{a:'Đúng. Mất mát rõ ràng, lợi ích mờ — người ta ngại quyết.',
      b:'Hợp đồng có thể kết thúc theo điều khoản; không phải rào cản chính.',
      c:'Tách được, chỉ cần làm; đây là lý do thực thi, không phải tâm lý.',
      d:'Đối thủ chiếm tệp lỗ cũng sẽ lỗ; ít khi là mối đe doạ thật.'} },
  { type:'mcq', stem:'Tình huống mới: một phòng gym có tệp khách vãng lai mua vé ngày, chiếm 15% doanh thu nhưng làm phòng chật giờ cao điểm, khiến hội viên năm phàn nàn. Hướng xử lý tốt nhất?',
    options:[{k:'a',t:'Giữ nguyên vì 15% doanh thu là khoản không nhỏ với phòng gym'},{k:'b',t:'Bỏ hẳn vé ngày và không cho khách vãng lai vào tập nữa'},
             {k:'c',t:'Tăng giá vé năm để bù phần hội viên phàn nàn và có thể rời đi'},{k:'d',t:'Chỉ bán vé ngày ngoài giờ cao điểm, bảo vệ tệp hội viên năm'}],
    answer:'d', why:{a:'Giữ nguyên làm hỏng trải nghiệm của tệp giá trị hơn.',
      b:'Bỏ hẳn khi có cách sửa rẻ là mất doanh thu không cần thiết.',
      c:'Tăng giá khi khách đang không vui làm họ rời nhanh hơn.',
      d:'Đúng. Sửa cách phục vụ để tệp phụ không làm hại tệp chính.'} },
  { type:'mcq', stem:'Chi phí nào KHÔNG nên tính vào chi phí phục vụ riêng của tệp đại lý tỉnh?',
    options:[{k:'a',t:'Tiền xăng và phí xe chở hàng chạy tuyến riêng về các tỉnh xa'},{k:'b',t:'Chiết khấu thêm chỉ dành riêng cho các đại lý ở tỉnh xa'},
             {k:'c',t:'Tiền thuê văn phòng chính, vẫn trả dù có đại lý tỉnh hay không'},{k:'d',t:'Lương nhân viên chỉ chuyên đi tuyến chăm sóc đại lý tỉnh'}],
    answer:'c', why:{a:'Xe chạy tuyến riêng là chi phí phát sinh vì tệp này.',
      b:'Chiết khấu riêng rõ ràng thuộc tệp này.',
      c:'Đúng. Chi phí chung không mất đi khi bỏ tệp, nên không tính vào quyết định bỏ.',
      d:'Nhân viên chuyên tuyến sẽ không cần nếu bỏ tệp.'} },
  { type:'mcq', stem:'Sau khi chuyển đại lý tỉnh cho nhà phân phối vùng, nên đo gì để biết quyết định đúng?',
    options:[{k:'a',t:'Tổng doanh thu năm của công ty so với năm ngoái'},{k:'b',t:'Lãi toàn công ty và tăng trưởng của tệp quán ăn được dồn lực'},
             {k:'c',t:'Số lượng đại lý tỉnh còn lại trong danh sách của nhà phân phối vùng'},{k:'d',t:'Số lượt nhắc tên thương hiệu trên mạng xã hội ở các tỉnh'}],
    answer:'b', why:{a:'Doanh thu có thể giảm mà lãi vẫn tăng; nhìn doanh thu dễ kết luận sai.',
      b:'Đúng. Mục đích bỏ tệp là tăng lãi và dồn lực — đo đúng hai thứ đó.',
      c:'Đó là việc của nhà phân phối, không cho biết quyết định của mình đúng không.',
      d:'Lượt nhắc không nói gì về lãi.'} }
  ] }

